#!/bin/bash
# Configure apt sources mirror
# 1. Detect OS, architecture, and codename
# 2. Backup existing sources (/etc/apt/sources.list.d/ubuntu.sources or /etc/apt/sources.list)
# 3. Write/update mirror URLs (DEB822 on Ubuntu 24.04+, legacy sources.list otherwise)
set -e
# shellcheck source=/dev/null
source "$(dirname "$(realpath "$0")")/../../lib/common.sh"

show_help() {
    cat <<EOF
Usage: main.sh apt mirror [mirror_url]

Configure apt sources to use a mirror.

Mirror URL is read from env/apt/mirror.conf (edit that file to change default).
CLI argument overrides the config file.

Default mirror: https://mirrors.tuna.tsinghua.edu.cn

Common mirrors:
  https://mirrors.tuna.tsinghua.edu.cn   (Tsinghua - default)
  https://mirrors.aliyun.com             (Aliyun)
  https://mirrors.ustc.edu.cn            (USTC)
  https://mirrors.163.com                (NetEase)
  https://mirrors.huaweicloud.com        (Huawei)

Steps:
  1. Detect OS (ubuntu/debian), architecture (ubuntu vs ubuntu-ports), and codename
  2. Backup existing sources file → *.bac.N
  3. Update DEB822 ubuntu.sources (Ubuntu 24.04+) or write /etc/apt/sources.list
  4. Run apt-get update

Options:
  -h, --help    Show this help message
EOF
}

if [ "${1:-}" = "-h" ] || [ "${1:-}" = "--help" ]; then
    show_help
    exit 0
fi

ENV_DIR="$(dirname "$(realpath "$0")")"

# Load mirror config from file (default)
MIRROR_CONF="$ENV_DIR/mirror.conf"
if [ -f "$MIRROR_CONF" ]; then
    # shellcheck source=/dev/null
    source "$MIRROR_CONF"
fi

# CLI argument overrides config file
if [ -n "${1:-}" ]; then
    MIRROR_URL="$1"
fi

MIRROR_URL="${MIRROR_URL:-https://mirrors.tuna.tsinghua.edu.cn}"
# Strip trailing slash
MIRROR_URL="${MIRROR_URL%/}"

# Detect OS
if [ -f /etc/os-release ]; then
    # shellcheck source=/dev/null
    . /etc/os-release
    OS="${ID:-}"
    CODENAME="${VERSION_CODENAME:-}"
else
    log_error "Cannot detect OS. /etc/os-release not found."
    exit 1
fi

case "$OS" in
    ubuntu|debian) ;;
    *)
        log_error "Unsupported OS: $OS (only ubuntu/debian are supported)"
        exit 1
        ;;
esac

if [ -z "$CODENAME" ]; then
    log_error "Cannot detect codename."
    exit 1
fi

ARCH="$(dpkg --print-architecture 2>/dev/null || uname -m)"
case "$ARCH" in
    amd64|i386|x86_64|i686) UBUNTU_REPO="ubuntu" ;;
    arm64|armhf|aarch64|armv7l|ppc64el|s390x|riscv64) UBUNTU_REPO="ubuntu-ports" ;;
    *) UBUNTU_REPO="ubuntu-ports" ;;
esac

log_info "Detected: $OS $CODENAME ($ARCH)"
log_info "Mirror:   $MIRROR_URL"

backup_and_install_sources() {
    local tmp_file="$1"
    local dst_file="$2"

    if [ -f "$dst_file" ]; then
        local n=0
        while [ -f "${dst_file}.bac.${n}" ]; do
            n=$((n + 1))
        done
        log_warn "Backing up $dst_file → ${dst_file}.bac.${n}"
        sudo cp "$dst_file" "${dst_file}.bac.${n}"
    fi

    sudo cp "$tmp_file" "$dst_file"
    rm -f "$tmp_file"
}

DEB822_SOURCES="/etc/apt/sources.list.d/ubuntu.sources"
SOURCES_LIST="/etc/apt/sources.list"
TMP_SOURCES="$(mktemp)"

if [ "$OS" = "ubuntu" ] && [ -f "$DEB822_SOURCES" ]; then
    log_info "Detected DEB822 apt sources: $DEB822_SOURCES"
    sed -E "s|^URIs:.*|URIs: ${MIRROR_URL}/${UBUNTU_REPO}/|" "$DEB822_SOURCES" > "$TMP_SOURCES"
    backup_and_install_sources "$TMP_SOURCES" "$DEB822_SOURCES"
else
    case "$OS" in
        ubuntu)
            cat > "$TMP_SOURCES" <<EOF
# Mirrored apt sources — $OS $CODENAME ($ARCH)
# Generated by setup-env apt mirror
# Mirror: $MIRROR_URL

deb $MIRROR_URL/$UBUNTU_REPO/ $CODENAME main restricted universe multiverse
deb $MIRROR_URL/$UBUNTU_REPO/ $CODENAME-updates main restricted universe multiverse
deb $MIRROR_URL/$UBUNTU_REPO/ $CODENAME-backports main restricted universe multiverse
deb $MIRROR_URL/$UBUNTU_REPO/ $CODENAME-security main restricted universe multiverse
EOF
            ;;
        debian)
            cat > "$TMP_SOURCES" <<EOF
# Mirrored apt sources — $OS $CODENAME ($ARCH)
# Generated by setup-env apt mirror
# Mirror: $MIRROR_URL

deb $MIRROR_URL/debian/ $CODENAME main contrib non-free non-free-firmware
deb $MIRROR_URL/debian/ $CODENAME-updates main contrib non-free non-free-firmware
deb $MIRROR_URL/debian/ $CODENAME-backports main contrib non-free non-free-firmware
deb $MIRROR_URL/debian-security/ $CODENAME-security main contrib non-free non-free-firmware
EOF
            ;;
    esac
    backup_and_install_sources "$TMP_SOURCES" "$SOURCES_LIST"
fi

log_info "Apt sources updated to mirror."
log_info "Running apt-get update..."
sudo apt-get update

log_info "Done. Apt mirror configured: $MIRROR_URL"
